#include <vector>
float2 makevertex(int i){if(i<150)return make_float2(float(i-75)/64,-75.f/64);if(i<300)return make_float2(75.f/64,float(i-225)/64);if(i<450)return make_float2(float(375-i)/64,75.f/64);return make_float2(-75.f/64,float(525-i)/64);}
int main(){const int n=16384;std::vector<float2>p(n),v(600);std::vector<int>want(n),out(n);for(int i=0;i<n;i++){p[i]=make_float2(float(2*(i%257)-255)/128,float(2*((17*i+3)%263)-261)/128);want[i]=fabsf(p[i].x)<75.f/64&&fabsf(p[i].y)<75.f/64;}for(int i=0;i<600;i++)v[i]=makevertex(i);float2*dp,*dv;int*dy;cudaMalloc(&dp,n*8);cudaMalloc(&dv,600*8);cudaMalloc(&dy,n*4);cudaMemcpy(dp,p.data(),n*8,cudaMemcpyHostToDevice);cudaMemcpy(dv,v.data(),600*8,cudaMemcpyHostToDevice);auto run=[&](int m){if(m==0)pnpoly_base<<<64,256>>>(dy,dp,dv,n);else if(m==1)pnpoly_opt<1><<<64,256>>>(dy,dp,dv,n);else if(m==2)pnpoly_opt<2><<<64,256>>>(dy,dp,dv,n);else if(m==4)pnpoly_opt<4><<<64,256>>>(dy,dp,dv,n);else if(m==8)pnpoly_opt<8><<<64,256>>>(dy,dp,dv,n);else if(m==16)pnpoly_opt<16><<<64,256>>>(dy,dp,dv,n);else if(m==32)pnpoly_opt<32><<<64,256>>>(dy,dp,dv,n);else pnpoly_opt<64><<<64,256>>>(dy,dp,dv,n);};int modes[]={0,1,2,4,8,16,32,64};for(int m:modes){run(m);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;}for(int trial=1;trial<=5;trial++){double total=0;bool ok=true;std::vector<int>all;for(int m:modes){cudaDeviceSynchronize();auto t=std::chrono::steady_clock::now();for(int k=0;k<10;k++)run(m);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/10;cudaMemcpy(out.data(),dy,n*4,cudaMemcpyDeviceToHost);for(int i=0;i<n;i++)ok=ok&&out[i]==want[i];all.insert(all.end(),out.begin(),out.end());}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(all.data(),4,all.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"timing_region\":\"sum_eight_case_bulk_kernel_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",all.size(),ok?0:1,path,all.size());if(!ok)return 1;}cudaFree(dp);cudaFree(dv);cudaFree(dy);}
